contract InvMutTest {
    C c;
    address beforeOwner;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        // record observable before-state
        beforeOwner = c.owner(); if (__ESBMC_reverted()) return;
        bool reverted;
        // attempt to call go forwarding `amount` wei
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        // After the call: either it reverted, or c must have zero balance and same owner
        assert(reverted || (address(c).balance == 0 && c.owner() == beforeOwner));
    }
    receive() external payable {}
}

